internal fun finnishMatchingCount(count: Int, noun: String): String {
    val adjective = if (count == 1) "vastaava" else "vastaavaa"
    return "$count $adjective ${localizedCountLabel(count, noun, AppLanguage.Finnish).substringAfter(' ')}"
}
